type StopHours = NonNullable<GuideStop["hours"]>;
type DayKey = "mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun";

function daily(rawText: string, defaultNote = `Daily ${rawText}.`): StopHours {
  return { default: defaultNote, mon: rawText, tue: rawText, wed: rawText, thu: rawText, fri: rawText, sat: rawText, sun: rawText };
}

function weekly(defaultNote: string, schedule: Partial<Record<DayKey, string>>): StopHours {
  return { default: defaultNote, ...schedule };
}

