function guide(
  id: string,
  title: string,
  category: ListCategory,
  seoSlug: string,
  seoTitle: string,
  seoDescription: string,
  description: string,
  stops: GuideStop[],
  guideSources: ListSource[],
  neighborhood?: string,
): MapList {
  return {
    id,
    slug: id,
    seoSlug,
    seoTitle,
    seoDescription,
    title,
    description,
    photo: stops[0]?.photo,
    url: `/list/${id}`,
    category,
    location: neighborhood ? { ...tokyoLocation, neighborhood, scope: "neighborhood" } : tokyoLocation,
    creator: {
      id: "rguide-editorial",
      name: "R Guide Editorial",
      avatar: avatar(category),
    },
    upvotes: 0,
    createdAt,
    stops,
    sources: guideSources,
  };
}

